from braincell.channel._base import HH,Gate
class Na(HH):
 root_type=braincell.HHTypedNeuron; gates=(Gate('m',3),Gate('h',1))
 def __init__(self,size,g=300*u.nS): super().__init__(size); self.g_max=g
 def current(self,V): return self.g_max*self.conductance_factor(V)*(50*u.mV-V)
 def f_m_alpha(self,V): x=(V.to_decimal(u.mV)-36+40)/10; return .1*u.math.exprel(-x)
 def f_m_beta(self,V): z=V.to_decimal(u.mV)-36; return .4*u.math.exp(-(z+65)/18)
