 def f_a_tau(self,V): return 8.
 def f_b_inf(self,V): return 1/(1+u.math.exp((V.to_decimal(u.mV)+25)/6))
 def f_b_tau(self,V): return 80.
class EGL(HH):
 root_type=braincell.HHTypedNeuron; gates=(Gate('c',2),Gate('d',1))
 def __init__(self,size,g=5*u.nS): super().__init__(size); self.g_max=g
 def current(self,V): return self.g_max*self.conductance_factor(V)*(60*u.mV-V)
 def f_c_inf(self,V): return 1/(1+u.math.exp(-(V.to_decimal(u.mV)+15)/5))
 def f_c_tau(self,V): return 5.
