 root_type=braincell.HHTypedNeuron; gates=(Gate('q',1),)
 def __init__(self,size,g=15*u.nS): super().__init__(size); self.g_max=g
 def current(self,V): return self.g_max*self.conductance_factor(V)*(-70*u.mV-V)
 def f_q_inf(self,V): return 1/(1+u.math.exp(-(V.to_decimal(u.mV)+5)/7))
 def f_q_tau(self,V): return 100.
class M(braincell.SingleCompartment):
 def __init__(self,C=2.5,gna=300,gkr=90,gshk=20,gegl=5,gslo=15,gl=.75):
  super().__init__(1,V_initializer=braintools.init.Constant(-29*u.mV),V_th=-10*u.mV,C=C*u.pF,solver='ind_exp_euler')
  self.Na=Na(1,gna*u.nS);self.Kr=Kr(1,gkr*u.nS);self.SHK1=SHK(1,gshk*u.nS);self.EGL19=EGL(1,gegl*u.nS);self.SLO2=SLO(1,gslo*u.nS);self.Leak=braincell.channel.IL(1,E=-29*u.mV,g_max=gl*u.nS)
def run(I,**p):
 m=M(**p);m.init_state();dt=.05*u.ms;ts=u.math.arange(0*u.ms,500*u.ms,dt)
 def step(t):
  with brainstate.environ.context(t=t):m.update(u.math.where((t>=50*u.ms)&(t<250*u.ms),I*u.pA,0*u.pA))
  return m.V.value
 with brainstate.environ.context(dt=dt):v=brainstate.transform.for_loop(step,ts)
 return np.asarray(v.to_decimal(u.mV)).squeeze()
for I in (15,20,25,30):
 a=run(I);cr=np.where((a[:-1]<-10)&(a[1:]>=-10))[0];print(I,a.min(),a.max(),len(cr),cr[:10]*.05,a[1000],a[5000],a[-1])
